import React, { useEffect, useState } from 'react';
import { toast } from 'react-toastify';
import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiPlay,
  FiVideo,
  FiEye,
  FiStar,
  FiGrid,
  FiCalendar,
  FiExternalLink,
} from 'react-icons/fi';

import api from '../../services/api';
import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';

const AdminVideos = () => {
  // =====================================================
  // STATE
  // =====================================================
  const [videos, setVideos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [modalOpen, setModalOpen] = useState(false);
  const [editingVideo, setEditingVideo] = useState(null);
  const [submitting, setSubmitting] = useState(false);

  const [formData, setFormData] = useState({
    title: '',
    description: '',
    video_url: '',
    thumbnail: '',
    category: '',
    date: '',
    is_featured: false,
  });

  const categories = [
    'School Activities',
    'Classroom',
    'Graduation',
    'Trips',
    'Special Events',
  ];

  // =====================================================
  // FETCH VIDEOS
  // =====================================================
  useEffect(() => {
    fetchVideos();
  }, []);

  const fetchVideos = async () => {
    try {
      setLoading(true);

      const response = await api.get('/api/videos/');

      setVideos(
        Array.isArray(response.data)
          ? response.data
          : []
      );
    } catch (error) {
      console.error('Fetch videos error:', error);
      toast.error('Failed to load videos');
    } finally {
      setLoading(false);
    }
  };

  // =====================================================
  // RESET FORM
  // =====================================================
  const resetForm = () => {
    setEditingVideo(null);

    setFormData({
      title: '',
      description: '',
      video_url: '',
      thumbnail: '',
      category: '',
      date: '',
      is_featured: false,
    });
  };

  // =====================================================
  // OPEN ADD MODAL
  // =====================================================
  const handleAdd = () => {
    resetForm();
    setModalOpen(true);
  };

  // =====================================================
  // CLOSE MODAL
  // =====================================================
  const handleCloseModal = () => {
    setModalOpen(false);
    resetForm();
  };

  // =====================================================
  // GET YOUTUBE ID
  // =====================================================
  const getYoutubeId = (url) => {
    if (!url) return null;

    try {
      if (url.includes('youtube.com/watch')) {
        const parsedUrl = new URL(url);
        return parsedUrl.searchParams.get('v');
      }

      if (url.includes('youtu.be/')) {
        return url
          .split('youtu.be/')[1]
          ?.split('?')[0];
      }

      if (url.includes('youtube.com/shorts/')) {
        return url
          .split('youtube.com/shorts/')[1]
          ?.split('?')[0];
      }

      if (url.includes('youtube.com/embed/')) {
        return url
          .split('youtube.com/embed/')[1]
          ?.split('?')[0];
      }

      return null;
    } catch {
      return null;
    }
  };

  // =====================================================
  // GET THUMBNAIL
  // =====================================================
  const getThumbnail = (video) => {
    if (video?.thumbnail) {
      return video.thumbnail;
    }

    const youtubeId = getYoutubeId(
      video?.video_url
    );

    if (youtubeId) {
      return `https://img.youtube.com/vi/${youtubeId}/hqdefault.jpg`;
    }

    return '';
  };

  // =====================================================
  // GET FORM THUMBNAIL
  // =====================================================
  const getFormThumbnail = () => {
    if (formData.thumbnail) {
      return formData.thumbnail;
    }

    const youtubeId = getYoutubeId(
      formData.video_url
    );

    if (youtubeId) {
      return `https://img.youtube.com/vi/${youtubeId}/hqdefault.jpg`;
    }

    return '';
  };

  // =====================================================
  // FORMAT DATE
  // =====================================================
  const formatDate = (date) => {
    if (!date) return '-';

    const parsed = new Date(date);

    if (Number.isNaN(parsed.getTime())) {
      return '-';
    }

    return parsed.toLocaleDateString();
  };

  // =====================================================
  // SUBMIT
  // =====================================================
  const handleSubmit = async (e) => {
    e.preventDefault();

    try {
      setSubmitting(true);

      if (editingVideo) {
        await api.put(
          `/api/videos/${editingVideo.id}`,
          formData
        );

        toast.success(
          'Video updated successfully'
        );
      } else {
        await api.post(
          '/api/videos/',
          formData
        );

        toast.success(
          'Video added successfully'
        );
      }

      handleCloseModal();

      await fetchVideos();
    } catch (error) {
      console.error(
        'Video operation error:',
        error
      );

      toast.error(
        error.response?.data?.detail ||
          'Operation failed'
      );
    } finally {
      setSubmitting(false);
    }
  };

  // =====================================================
  // EDIT
  // =====================================================
  const handleEdit = (video) => {
    setEditingVideo(video);

    setFormData({
      title: video.title || '',
      description:
        video.description || '',
      video_url:
        video.video_url || '',
      thumbnail:
        video.thumbnail || '',
      category:
        video.category || '',
      date: video.date
        ? video.date.slice(0, 16)
        : '',
      is_featured: Boolean(
        video.is_featured
      ),
    });

    setModalOpen(true);
  };

  // =====================================================
  // DELETE
  // =====================================================
  const handleDelete = async (id) => {
    const confirmed = window.confirm(
      'Are you sure you want to delete this video?'
    );

    if (!confirmed) return;

    try {
      await api.delete(
        `/api/videos/${id}`
      );

      toast.success(
        'Video deleted successfully'
      );

      await fetchVideos();
    } catch (error) {
      console.error(
        'Delete video error:',
        error
      );

      toast.error(
        error.response?.data?.detail ||
          'Failed to delete video'
      );
    }
  };

  // =====================================================
  // OPEN VIDEO
  // =====================================================
  const handleOpenVideo = (url) => {
    if (!url) return;

    window.open(
      url,
      '_blank',
      'noopener,noreferrer'
    );
  };

  // =====================================================
  // SUMMARY
  // =====================================================
  const featuredCount = videos.filter(
    (video) => video.is_featured
  ).length;

  const totalViews = videos.reduce(
    (total, video) =>
      total + Number(video.views || 0),
    0
  );

  const categoryCount = new Set(
    videos
      .map((video) => video.category)
      .filter(Boolean)
  ).size;

  // =====================================================
  // TABLE COLUMNS
  // =====================================================
  const columns = [
    {
      key: 'thumbnail',
      label: 'Video',
      render: (_, row) => {
        const thumbnail =
          getThumbnail(row);

        return (
          <div
            className="
              relative
              w-[105px]
              h-[62px]
              bg-gray-100
              rounded-lg
              overflow-hidden
              flex-shrink-0
              group
            "
          >
            {thumbnail ? (
              <img
                src={thumbnail}
                alt={row.title || 'Video'}
                className="
                  w-full
                  h-full
                  object-cover
                "
                onError={(e) => {
                  e.currentTarget.style.display =
                    'none';
                }}
              />
            ) : (
              <div
                className="
                  w-full
                  h-full
                  flex
                  items-center
                  justify-center
                  text-gray-300
                "
              >
                <FiVideo size={22} />
              </div>
            )}

            <button
              type="button"
              onClick={() =>
                handleOpenVideo(
                  row.video_url
                )
              }
              className="
                absolute
                inset-0
                bg-black/20
                flex
                items-center
                justify-center
                opacity-0
                group-hover:opacity-100
                transition
              "
            >
              <div
                className="
                  w-8
                  h-8
                  bg-red-500
                  text-white
                  rounded-full
                  flex
                  items-center
                  justify-center
                  shadow
                "
              >
                <FiPlay
                  size={14}
                  className="ml-0.5"
                />
              </div>
            </button>
          </div>
        );
      },
    },

    {
      key: 'title',
      label: 'Title',
      render: (val, row) => (
        <div className="max-w-[240px]">
          <div className="flex items-center gap-2">
            <p
              className="
                font-semibold
                text-blue-900
                truncate
              "
            >
              {val || 'Untitled'}
            </p>

            {row.is_featured && (
              <FiStar
                size={13}
                className="
                  text-yellow-500
                  fill-current
                  flex-shrink-0
                "
              />
            )}
          </div>

          {row.description && (
            <p
              className="
                text-xs
                text-gray-400
                truncate
                mt-1
              "
            >
              {row.description}
            </p>
          )}
        </div>
      ),
    },

    {
      key: 'category',
      label: 'Category',
      render: (val) =>
        val ? (
          <span
            className="
              inline-flex
              px-2.5
              py-1
              bg-blue-50
              text-blue-800
              rounded-full
              text-[11px]
              font-semibold
              whitespace-nowrap
            "
          >
            {val}
          </span>
        ) : (
          <span className="text-gray-300">
            -
          </span>
        ),
    },

    {
      key: 'date',
      label: 'Date',
      render: (val) => (
        <div
          className="
            flex
            items-center
            gap-1.5
            text-sm
            text-gray-600
            whitespace-nowrap
          "
        >
          <FiCalendar
            size={13}
            className="text-red-500"
          />

          {formatDate(val)}
        </div>
      ),
    },

    {
      key: 'views',
      label: 'Views',
      render: (val) => (
        <div
          className="
            inline-flex
            items-center
            gap-1.5
            text-sm
            text-gray-600
          "
        >
          <FiEye
            size={14}
            className="text-gray-400"
          />

          {Number(val || 0).toLocaleString()}
        </div>
      ),
    },

    {
      key: 'actions',
      label: 'Actions',
      render: (_, row) => (
        <div
          className="
            flex
            items-center
            gap-2
          "
        >
          {/* PLAY */}
          <button
            type="button"
            onClick={() =>
              handleOpenVideo(
                row.video_url
              )
            }
            className="
              w-8
              h-8
              flex
              items-center
              justify-center
              bg-green-50
              text-green-600
              rounded-lg
              hover:bg-green-500
              hover:text-white
              transition
            "
            title="Watch video"
          >
            <FiPlay size={14} />
          </button>

          {/* EDIT */}
          <button
            type="button"
            onClick={() =>
              handleEdit(row)
            }
            className="
              w-8
              h-8
              flex
              items-center
              justify-center
              bg-blue-50
              text-blue-700
              rounded-lg
              hover:bg-blue-900
              hover:text-white
              transition
            "
            title="Edit video"
          >
            <FiEdit2 size={14} />
          </button>

          {/* DELETE */}
          <button
            type="button"
            onClick={() =>
              handleDelete(row.id)
            }
            className="
              w-8
              h-8
              flex
              items-center
              justify-center
              bg-red-50
              text-red-500
              rounded-lg
              hover:bg-red-500
              hover:text-white
              transition
            "
            title="Delete video"
          >
            <FiTrash2 size={14} />
          </button>
        </div>
      ),
    },
  ];

  const formThumbnail =
    getFormThumbnail();

  return (
    <div className="w-full">

      {/* =================================================
          HEADER
      ================================================== */}
      <div
        className="
          flex
          flex-col
          sm:flex-row
          sm:items-center
          sm:justify-between
          gap-4
          mb-6
        "
      >
        <div className="flex items-center gap-3">
          <div
            className="
              w-10
              h-10
              bg-blue-900
              text-white
              rounded-xl
              flex
              items-center
              justify-center
              shadow-sm
            "
          >
            <FiVideo size={18} />
          </div>

          <div>
            <h1
              className="
                text-xl
                md:text-2xl
                font-bold
                text-blue-900
              "
            >
              Videos Management
            </h1>

            <p
              className="
                text-xs
                md:text-sm
                text-gray-500
                mt-1
              "
            >
              Manage SC Academy videos,
              activities and highlights
            </p>
          </div>
        </div>

        <button
          type="button"
          onClick={handleAdd}
          className="
            h-10
            px-4
            inline-flex
            items-center
            justify-center
            gap-2
            bg-red-500
            text-white
            rounded-lg
            text-sm
            font-semibold
            shadow-sm
            hover:bg-red-600
            hover:shadow-md
            transition-all
          "
        >
          <FiPlus size={17} />

          Add Video
        </button>
      </div>

      {/* =================================================
          SUMMARY CARDS
      ================================================== */}
      <div
        className="
          grid
          grid-cols-2
          xl:grid-cols-4
          gap-3
          mb-6
        "
      >
        {/* TOTAL */}
        <div
          className="
            bg-white
            border
            border-gray-100
            rounded-xl
            p-4
            shadow-sm
          "
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs text-gray-500">
                Total Videos
              </p>

              <p
                className="
                  text-2xl
                  font-bold
                  text-blue-900
                  mt-1
                "
              >
                {videos.length}
              </p>
            </div>

            <div
              className="
                w-10
                h-10
                bg-blue-50
                text-blue-900
                rounded-lg
                flex
                items-center
                justify-center
              "
            >
              <FiVideo size={18} />
            </div>
          </div>
        </div>

        {/* FEATURED */}
        <div
          className="
            bg-white
            border
            border-gray-100
            rounded-xl
            p-4
            shadow-sm
          "
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs text-gray-500">
                Featured
              </p>

              <p
                className="
                  text-2xl
                  font-bold
                  text-yellow-600
                  mt-1
                "
              >
                {featuredCount}
              </p>
            </div>

            <div
              className="
                w-10
                h-10
                bg-yellow-50
                text-yellow-600
                rounded-lg
                flex
                items-center
                justify-center
              "
            >
              <FiStar size={18} />
            </div>
          </div>
        </div>

        {/* VIEWS */}
        <div
          className="
            bg-white
            border
            border-gray-100
            rounded-xl
            p-4
            shadow-sm
          "
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs text-gray-500">
                Total Views
              </p>

              <p
                className="
                  text-2xl
                  font-bold
                  text-green-600
                  mt-1
                "
              >
                {totalViews.toLocaleString()}
              </p>
            </div>

            <div
              className="
                w-10
                h-10
                bg-green-50
                text-green-600
                rounded-lg
                flex
                items-center
                justify-center
              "
            >
              <FiEye size={18} />
            </div>
          </div>
        </div>

        {/* CATEGORIES */}
        <div
          className="
            bg-white
            border
            border-gray-100
            rounded-xl
            p-4
            shadow-sm
          "
        >
          <div className="flex items-center justify-between">
            <div>
              <p className="text-xs text-gray-500">
                Categories
              </p>

              <p
                className="
                  text-2xl
                  font-bold
                  text-red-500
                  mt-1
                "
              >
                {categoryCount}
              </p>
            </div>

            <div
              className="
                w-10
                h-10
                bg-red-50
                text-red-500
                rounded-lg
                flex
                items-center
                justify-center
              "
            >
              <FiGrid size={18} />
            </div>
          </div>
        </div>
      </div>

      {/* =================================================
          TABLE
      ================================================== */}
      <AdminCard
        className="
          border
          border-gray-100
          rounded-xl
          shadow-sm
          overflow-hidden
        "
      >
        <div
          className="
            px-5
            py-4
            border-b
            border-gray-100
            flex
            items-center
            justify-between
          "
        >
          <div>
            <h2
              className="
                text-sm
                font-bold
                text-blue-900
              "
            >
              All Videos
            </h2>

            <p
              className="
                text-xs
                text-gray-400
                mt-1
              "
            >
              {videos.length}{' '}
              {videos.length === 1
                ? 'video'
                : 'videos'}{' '}
              found
            </p>
          </div>
        </div>

        <AdminTable
          columns={columns}
          data={videos}
          loading={loading}
        />
      </AdminCard>

      {/* =================================================
          MODAL
      ================================================== */}
      <AdminModal
        isOpen={modalOpen}
        onClose={handleCloseModal}
        title={
          editingVideo
            ? 'Edit Video'
            : 'Add Video'
        }
      >
        <form onSubmit={handleSubmit}>
          <div className="space-y-4">

            {/* TITLE */}
            <div>
              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-gray-700
                  mb-1.5
                "
              >
                Video Title
                <span className="text-red-500">
                  {' '}*
                </span>
              </label>

              <input
                type="text"
                value={formData.title}
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    title:
                      e.target.value,
                  })
                }
                placeholder="Enter video title"
                className="
                  w-full
                  h-11
                  px-3.5
                  border
                  border-gray-200
                  rounded-lg
                  text-sm
                  outline-none
                  focus:border-blue-900
                  focus:ring-2
                  focus:ring-blue-900/10
                  transition
                "
                required
              />
            </div>

            {/* DESCRIPTION */}
            <div>
              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-gray-700
                  mb-1.5
                "
              >
                Description
              </label>

              <textarea
                value={
                  formData.description
                }
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    description:
                      e.target.value,
                  })
                }
                rows="3"
                placeholder="Write a short description..."
                className="
                  w-full
                  px-3.5
                  py-3
                  border
                  border-gray-200
                  rounded-lg
                  text-sm
                  resize-none
                  outline-none
                  focus:border-blue-900
                  focus:ring-2
                  focus:ring-blue-900/10
                  transition
                "
              />
            </div>

            {/* VIDEO URL */}
            <div>
              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-gray-700
                  mb-1.5
                "
              >
                Video URL
                <span className="text-red-500">
                  {' '}*
                </span>
              </label>

              <div className="relative">
                <input
                  type="url"
                  value={
                    formData.video_url
                  }
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      video_url:
                        e.target.value,
                    })
                  }
                  placeholder="https://www.youtube.com/watch?v=..."
                  className="
                    w-full
                    h-11
                    pl-3.5
                    pr-10
                    border
                    border-gray-200
                    rounded-lg
                    text-sm
                    outline-none
                    focus:border-blue-900
                    focus:ring-2
                    focus:ring-blue-900/10
                    transition
                  "
                  required
                />

                <FiExternalLink
                  className="
                    absolute
                    right-3.5
                    top-1/2
                    -translate-y-1/2
                    text-gray-400
                  "
                />
              </div>

              <p
                className="
                  text-[10px]
                  text-gray-400
                  mt-1.5
                "
              >
                Supports YouTube,
                YouTube Shorts and
                Facebook video links.
              </p>
            </div>

            {/* =================================================
                THUMBNAIL PREVIEW
            ================================================== */}
            {formThumbnail && (
              <div>
                <label
                  className="
                    block
                    text-sm
                    font-semibold
                    text-gray-700
                    mb-1.5
                  "
                >
                  Thumbnail Preview
                </label>

                <div
                  className="
                    relative
                    w-full
                    h-[200px]
                    rounded-xl
                    overflow-hidden
                    bg-gray-100
                    group
                  "
                >
                  <img
                    src={formThumbnail}
                    alt="Thumbnail Preview"
                    className="
                      w-full
                      h-full
                      object-cover
                    "
                  />

                  <div
                    className="
                      absolute
                      inset-0
                      bg-black/20
                      flex
                      items-center
                      justify-center
                    "
                  >
                    <div
                      className="
                        w-12
                        h-12
                        bg-red-500
                        text-white
                        rounded-full
                        flex
                        items-center
                        justify-center
                        shadow-lg
                      "
                    >
                      <FiPlay
                        size={19}
                        className="ml-1"
                      />
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* THUMBNAIL URL */}
            <div>
              <label
                className="
                  block
                  text-sm
                  font-semibold
                  text-gray-700
                  mb-1.5
                "
              >
                Thumbnail URL
              </label>

              <input
                type="url"
                value={
                  formData.thumbnail
                }
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    thumbnail:
                      e.target.value,
                  })
                }
                placeholder="Optional - YouTube thumbnail is automatic"
                className="
                  w-full
                  h-11
                  px-3.5
                  border
                  border-gray-200
                  rounded-lg
                  text-sm
                  outline-none
                  focus:border-blue-900
                  focus:ring-2
                  focus:ring-blue-900/10
                  transition
                "
              />

              <p
                className="
                  text-[10px]
                  text-gray-400
                  mt-1.5
                "
              >
                Leave empty for YouTube
                videos to generate the
                thumbnail automatically.
              </p>
            </div>

            {/* CATEGORY + DATE */}
            <div
              className="
                grid
                grid-cols-1
                md:grid-cols-2
                gap-4
              "
            >
              {/* CATEGORY */}
              <div>
                <label
                  className="
                    block
                    text-sm
                    font-semibold
                    text-gray-700
                    mb-1.5
                  "
                >
                  Category
                </label>

                <select
                  value={
                    formData.category
                  }
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      category:
                        e.target.value,
                    })
                  }
                  className="
                    w-full
                    h-11
                    px-3.5
                    bg-white
                    border
                    border-gray-200
                    rounded-lg
                    text-sm
                    outline-none
                    focus:border-blue-900
                    focus:ring-2
                    focus:ring-blue-900/10
                  "
                >
                  <option value="">
                    Select Category
                  </option>

                  {categories.map(
                    (category) => (
                      <option
                        key={category}
                        value={category}
                      >
                        {category}
                      </option>
                    )
                  )}
                </select>
              </div>

              {/* DATE */}
              <div>
                <label
                  className="
                    block
                    text-sm
                    font-semibold
                    text-gray-700
                    mb-1.5
                  "
                >
                  Date
                  <span className="text-red-500">
                    {' '}*
                  </span>
                </label>

                <input
                  type="datetime-local"
                  value={formData.date}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      date:
                        e.target.value,
                    })
                  }
                  className="
                    w-full
                    h-11
                    px-3.5
                    border
                    border-gray-200
                    rounded-lg
                    text-sm
                    outline-none
                    focus:border-blue-900
                    focus:ring-2
                    focus:ring-blue-900/10
                  "
                  required
                />
              </div>
            </div>

            {/* FEATURED */}
            <label
              className={`
                flex
                items-center
                gap-3
                p-3.5
                border
                rounded-xl
                cursor-pointer
                transition-all

                ${
                  formData.is_featured
                    ? `
                      border-yellow-300
                      bg-yellow-50
                    `
                    : `
                      border-gray-200
                      bg-white
                    `
                }
              `}
            >
              <input
                type="checkbox"
                checked={
                  formData.is_featured
                }
                onChange={(e) =>
                  setFormData({
                    ...formData,
                    is_featured:
                      e.target.checked,
                  })
                }
                className="
                  w-4
                  h-4
                  accent-yellow-500
                "
              />

              <div
                className="
                  w-9
                  h-9
                  bg-yellow-100
                  text-yellow-600
                  rounded-lg
                  flex
                  items-center
                  justify-center
                "
              >
                <FiStar size={16} />
              </div>

              <div>
                <p
                  className="
                    text-sm
                    font-semibold
                    text-gray-700
                  "
                >
                  Featured Video
                </p>

                <p
                  className="
                    text-[10px]
                    text-gray-400
                    mt-0.5
                  "
                >
                  Highlight this video
                  on the website
                </p>
              </div>
            </label>
          </div>

          {/* =================================================
              MODAL FOOTER
          ================================================== */}
          <div
            className="
              mt-6
              pt-4
              border-t
              border-gray-100
              flex
              items-center
              justify-end
              gap-3
            "
          >
            <button
              type="button"
              onClick={
                handleCloseModal
              }
              disabled={submitting}
              className="
                h-10
                px-4
                bg-white
                border
                border-gray-200
                text-gray-600
                rounded-lg
                text-sm
                font-semibold
                hover:bg-gray-50
                transition
              "
            >
              Cancel
            </button>

            <button
              type="submit"
              disabled={submitting}
              className="
                min-w-[110px]
                h-10
                px-5
                bg-red-500
                text-white
                rounded-lg
                text-sm
                font-semibold
                hover:bg-red-600
                disabled:opacity-50
                disabled:cursor-not-allowed
                transition
              "
            >
              {submitting
                ? editingVideo
                  ? 'Updating...'
                  : 'Adding...'
                : editingVideo
                ? 'Update Video'
                : 'Add Video'}
            </button>
          </div>
        </form>
      </AdminModal>
    </div>
  );
};

export default AdminVideos;
